linuxContainer.runner:
#!/usr/bin/env bash
set -euo pipefail
repo=/Users/liusinan/apps/ideaproject/nereusstream/bookkeeper
mkdir -p /work/lib
id -u
cat /proc/self/status | grep -E 'Cpus_allowed_list|Mems_allowed_list'
cat /sys/fs/cgroup/cpu.max
gcc -std=gnu11 -shared -fPIC -Werror=implicit-function-declaration \
  -I"$JAVA_HOME/include" -I"$JAVA_HOME/include/linux" \
  -I"$repo/cpu-affinity/target/nar/javah-include" \
  "$repo/cpu-affinity/src/main/affinity/cpp/affinity_jni.c" -o /work/lib/libcpu-affinity.so
cp_value="$(cat /input/classpath)"
cat > /work/RuntimeTests.java <<'JAVA'
import org.junit.runner.JUnitCore;
import org.junit.runner.Result;
import org.junit.runner.notification.RunListener;
import org.junit.runner.notification.Failure;
import org.junit.runner.Description;
public class RuntimeTests {
  public static void main(String[] args) throws Exception {
    JUnitCore core = new JUnitCore();
    core.addListener(new RunListener() {
      public void testStarted(Description d) { System.out.println("START " + d.getClassName() + "." + d.getMethodName()); }
      public void testAssumptionFailure(Failure f) { System.out.println("SKIP " + f); }
      public void testFailure(Failure f) { System.out.println("FAIL " + f.getTrace()); }
    });
    Result r = core.run(
      org.apache.bookkeeper.common.util.affinity.CpuBindingTest.class,
      org.apache.bookkeeper.common.util.affinity.CpuTopologySnapshotTest.class,
      org.apache.bookkeeper.bookie.storage.segment.SegmentExecutionGroupTest.class,
      org.apache.bookkeeper.bookie.storage.segment.SegmentOwnerLoopTest.class);
    System.out.println("tests=" + r.getRunCount() + " failures=" + r.getFailureCount()
      + " assumptions=" + r.getAssumptionFailureCount());
    if (!r.wasSuccessful()) System.exit(1);
  }
}
JAVA
javac -proc:none -cp "$cp_value" -d /work /work/RuntimeTests.java
java -Duw.requireBinding=true -cp "$cp_value" RuntimeTests

