#!/usr/bin/env bash
set -euo pipefail
repo=/Users/liusinan/apps/ideaproject/nereusstream/bookkeeper
mkdir -p /work/lib
cat /proc/self/status | grep Cpus_allowed_list
cat /sys/fs/cgroup/cpu.max
gcc -std=gnu11 -shared -fPIC -Werror=implicit-function-declaration \
  -I"$JAVA_HOME/include" -I"$JAVA_HOME/include/linux" \
  -I"$repo/cpu-affinity/target/nar/javah-include" \
  "$repo/cpu-affinity/src/main/affinity/cpp/affinity_jni.c" -o /work/lib/libcpu-affinity.so
cat > /work/FallbackTests.java <<'JAVA'
import org.junit.runner.JUnitCore;
import org.junit.runner.Request;
import org.junit.runner.Result;
public class FallbackTests {
  public static void main(String[] args) {
    Result result = new JUnitCore().run(Request.method(
      org.apache.bookkeeper.bookie.storage.segment.SegmentExecutionGroupTest.class,
      "linuxPreferStartupFallsBackOffWhenQuotaCannotSupportTheBoundPlan"));
    result.getFailures().forEach(f -> System.out.println(f.getTrace()));
    System.out.println("tests=" + result.getRunCount() + " failures=" + result.getFailureCount()
      + " assumptions=" + result.getAssumptionFailureCount());
    if (!result.wasSuccessful() || result.getRunCount() != 1 || result.getAssumptionFailureCount() != 0) {
      System.exit(1);
    }
  }
}
JAVA
cp_value="$(cat /input/classpath)"
javac -proc:none -cp "$cp_value" -d /work /work/FallbackTests.java
java -Duw.expectStartupFallback=true -cp "$cp_value" FallbackTests
